 const controls=`<div class="branch-toolbar"><div class="branch-expand-controls">${focusId!==idx.root.id?'<button class="btn" id="whole-tree">Gesamtbaum</button>':''}<button class="btn primary" id="expand-all" ${!root.count?'disabled':''}>Alles aufklappen</button><button class="btn" id="collapse" ${!root.count?'disabled':''}>Zuklappen</button></div></div>`;
 if(!root.count)return `${crumbs()}${controls}<p class="empty">Keine Arten für diesen Filter.</p>`;
