function focusTaxon(id){if(graphMode==='step'&&tab==='tree'&&!query.trim()){openStep(id);return;}rememberView();searchOrigin=null;if(active.nodes.find(n=>n.id===id)?.rank==='subspecies')subspeciesView=true;siblingQuery='';query='';tab='tree';refreshIndex();overviewListQuery='';overviewShowAll=false;focusId=id;selectedId=id;listScroll=0;open.clear();branchPages.clear();graphState={};render();finishNavigation();}
