async function checkUpdate(){const button=$('#check');button.disabled=true;$('#check-status').textContent='Prüfe das Updateverzeichnis …';try{const r=await fetch('./releases.json',{cache:'no-store'});if(!r.ok)throw Error('Updateverzeichnis nicht erreichbar.');const m=await r.json();if(m.version===active.version&&m.source_sha256===active.source.sha256&&m.sha256===await digest(new TextEncoder().encode(JSON.stringify(active)))){checkMessage='Kein neuer bereitgestellter Datenstand. Letzte Prüfung: '+new Date().toLocaleString('de-DE');$('#check-status').textContent=checkMessage;return;}if(typeof m.path!=='string'||!/^releases\/[a-zA-Z0-9.-]+\.json$/.test(m.path)||!/^[0-9a-f]{64}$/.test(m.sha256))throw Error('Ungültiges Updateverzeichnis.');const res=await fetch(m.path,{cache:'no-store'});if(!res.ok)throw Error('Updatepaket nicht erreichbar.');const bytes=await res.arrayBuffer();if(bytes.byteLength>20*1024*1024)throw Error('Updatepaket zu groß.');const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');if(hash!==m.sha256)throw Error('Prüfsumme stimmt nicht überein.');const next=JSON.parse(new TextDecoder().decode(bytes)),errors=validate(next);if(errors.length)throw Error(errors.slice(0,3).join('; '));if(next.version!==m.version||next.source.sha256!==m.source_sha256)throw Error('Versionsangaben stimmen nicht überein.');staged=next;stagedBaseline=active;stagedDiff=compare(stagedBaseline,next);stageKind='release';checkMessage='Neuer bereitgestellter Datenstand geladen. Vergleich unten prüfen.';$('#check-status').textContent=checkMessage;showDiff();}catch(e){checkMessage='Prüfung fehlgeschlagen: '+e.message+' Der bisherige Stand bleibt verfügbar.';$('#check-status').textContent=checkMessage;}finally{button.disabled=false;}}
